// Shared library scenes for small molecules the dives end at, with
// geometry generated by RDKit (tools/gen_molecules.py). 1 scene unit = 1 Å.
//   glucose        β-D-glucose, the sugar the small intestine absorbs (digestive dive)
//   acetylcholine  the messenger at the nerve–muscle junction (reflex arc module)
//   histamine      the alarm signal mast cells release (inflammatory response module)
//   urea           the nitrogen waste the kidney filters out (urinary dive)
//   thyroxine      the thyroid hormone, with T3 beside it (endocrine dive)
//   vitamin-d3     cholecalciferol, made in sunlit skin (skin dive)
//   retinal        11-cis and all-trans, the switch light flips (eye dive)
//   bilirubin      the yellow pigment made from heme (liver dive)
//   vanillin       the scent of vanilla (smell dive)
import * as THREE from 'three/webgpu';
import { materialBank, disposeTree } from '../scenes/kit.js';
import { buildMolecule, styleControls } from './molecule.js';
import { moleculeGraph } from './molecules.js';

const neighbors = (bonds, i) => bonds.filter(([a, b]) => a === i || b === i).map(([a, b]) => (a === i ? b : a));

/** Glucose atoms labeled by role: ring oxygen, ring carbons, hydroxyl groups, the CH₂OH arm. */
export function glucoseParts() {
  const { atoms, bonds } = moleculeGraph('glucose');
  const ringO = atoms.findIndex((a, i) => a.el === 'O' && neighbors(bonds, i).filter((k) => atoms[k].el === 'C').length === 2);
  // Carbon 1 (anomeric): bonded to the ring oxygen and to a second oxygen. Carbon 5: the ring oxygen's other carbon.
  const ringOC = neighbors(bonds, ringO);
  const c1 = ringOC.find((k) => neighbors(bonds, k).filter((o) => atoms[o].el === 'O').length === 2);
  const c5 = ringOC.find((k) => k !== c1);
  const c6 = neighbors(bonds, c5).find((k) => atoms[k].el === 'C' && !ringOC.includes(k) && neighbors(bonds, k).filter((o) => atoms[o].el === 'C').length === 1);
  const role = atoms.map((a, i) => {
    if (i === ringO) return ['ring', 'Ring oxygen'];
    if (i === c1) return ['ring', 'Carbon 1 (its –OH points the same side as carbon 6: the β form)'];
    if (i === c6) return ['arm', 'Carbon 6 (the CH₂OH arm)'];
    if (a.el === 'C') return ['ring', 'Ring carbon'];
    if (a.el === 'O') return ['oh', 'Oxygen of a hydroxyl group (–OH)'];
    return null;
  });
  atoms.forEach((a, i) => {
    if (a.el === 'H') {
      const heavy = neighbors(bonds, i)[0];
      role[i] = atoms[heavy].el === 'O' ? ['oh', 'Hydrogen of a hydroxyl group'] : ['h', 'Hydrogen'];
    }
  });
  return { atoms, bonds, role, ringO, c1, c6 };
}

/** Acetylcholine split at its ester bond into the acetyl part and the choline part. */
export function acetylcholineParts() {
  const { atoms, bonds } = moleculeGraph('acetylcholine');
  const carbonyl = atoms.findIndex((a, i) => a.el === 'C' && neighbors(bonds, i).filter((k) => atoms[k].el === 'O').length === 2);
  const esterO = neighbors(bonds, carbonyl).find((k) => atoms[k].el === 'O' && neighbors(bonds, k).length === 2);
  const nitrogen = atoms.findIndex((a) => a.el === 'N');
  // Everything reachable from the carbonyl carbon without crossing the ester bond is the acetyl part.
  const acetyl = new Set([carbonyl]);
  const stack = [carbonyl];
  while (stack.length) {
    const i = stack.pop();
    for (const k of neighbors(bonds, i)) {
      if (acetyl.has(k) || (i === carbonyl && k === esterO)) continue;
      acetyl.add(k);
      stack.push(k);
    }
  }
  return { atoms, bonds, carbonyl, esterO, nitrogen, acetyl };
}

function spinRoot(reducedMotion) {
  const root = new THREE.Group();
  const spin = new THREE.Group();
  root.add(spin);
  return { root, spin, update: (dt) => !reducedMotion && (spin.rotation.y += dt * 0.3) };
}

export function buildGlucose({ reducedMotion = false } = {}) {
  const M = materialBank();
  const { root, spin, update } = spinRoot(reducedMotion);
  const { atoms, bonds, role } = glucoseParts();
  const TINT = { ring: 0x8f7ff0, oh: 0x5a8deb, arm: 0xf2a65a };
  atoms.forEach((a, i) => {
    const [part, label] = role[i];
    Object.assign(a, { label, card: part === 'oh' ? 'hydroxyl-group' : 'glucose', tint: TINT[part] });
  });
  const mol = buildMolecule(atoms, bonds, M, { defaultCard: 'glucose' });
  spin.add(mol.group);
  const controls = styleControls([mol], [
    'Ball and stick: a ring of five carbons and one oxygen, five –OH groups and a CH₂OH arm. C₆H₁₂O₆, 24 atoms.',
    'Space filling: the whole molecule is under 1 nm across. All those –OH groups let water cling to it, which is why sugar dissolves so easily.',
  ]);
  controls.set(0);
  return {
    root,
    fit: 'both',
    metersPerUnit: 1e-10,
    view: { target: [0, 0, 0], direction: [0.15, 0.55, 1] },
    focus: [0, 0, 0],
    controls,
    update,
    dispose() {
      mol.sphere.dispose();
      disposeTree(root);
      M.dispose();
    },
  };
}

export function buildAcetylcholine({ reducedMotion = false } = {}) {
  const M = materialBank();
  const { root, spin, update: turn } = spinRoot(reducedMotion);
  const { atoms, bonds, esterO, nitrogen, acetyl } = acetylcholineParts();
  atoms.forEach((a, i) => {
    const inAcetyl = acetyl.has(i);
    a.tint = inAcetyl ? 0xf2a65a : 0x7cc49a;
    a.card = 'acetylcholine';
    a.label = i === nitrogen ? 'Nitrogen (carries the +1 charge)' : i === esterO ? 'Ester oxygen (the enzyme cuts next to it)' : inAcetyl ? 'Acetyl part (becomes acetate)' : 'Choline part (recycled into new acetylcholine)';
  });
  // Two molecules' worth of atoms: the acetyl part can slide away when the enzyme cuts the bond.
  const idxA = [...acetyl];
  const idxC = atoms.map((_, i) => i).filter((i) => !acetyl.has(i));
  const sub = (idx) => {
    const map = new Map(idx.map((old, k) => [old, k]));
    return buildMolecule(idx.map((i) => atoms[i]), bonds.filter(([i, j]) => map.has(i) && map.has(j)).map(([i, j, o]) => [map.get(i), map.get(j), o]), M, { defaultCard: 'acetylcholine' });
  };
  const acetylMol = sub(idxA);
  const cholineMol = sub(idxC);
  const acetylGroup = new THREE.Group();
  acetylGroup.add(acetylMol.group);
  spin.add(acetylGroup, cholineMol.group);
  // The ester bond, drawn on its own so it can break.
  const carb = [...acetyl].find((i) => bonds.some(([a, b]) => (a === i && b === esterO) || (b === i && a === esterO)));
  const bondGeo = new THREE.CylinderGeometry(0.11, 0.11, 1, 10);
  const bondMesh = new THREE.Mesh(bondGeo, M(0xff7a3d, { roughness: 0.4, emissive: 0xff7a3d, emissiveIntensity: 0.5 }));
  const a = atoms[carb].p;
  const b = atoms[esterO].p;
  bondMesh.position.copy(a).add(b).multiplyScalar(0.5);
  bondMesh.scale.y = a.distanceTo(b);
  bondMesh.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), b.clone().sub(a).normalize());
  bondMesh.userData = { cardId: 'acetylcholinesterase', label: 'Ester bond (acetylcholinesterase breaks it)' };
  spin.add(bondMesh);
  const away = a.clone().sub(b).normalize();

  const controls = {
    label: 'Enzyme',
    unit: '',
    min: 0,
    max: 1,
    step: 0.01,
    value: 0,
    format: (v) => (v < 0.5 ? 'Whole molecule' : 'Cut by the enzyme'),
    presets: [
      { label: 'Whole molecule', value: 0 },
      { label: 'Cut by the enzyme', value: 1 },
    ],
    set(v) {
      controls.value = v;
      acetylGroup.position.copy(away).multiplyScalar(3.2 * v);
      bondMesh.visible = v < 0.5;
      return v < 0.5
        ? 'Acetylcholine, C₇H₁₆NO₂⁺: an acetyl group (orange) joined by an ester bond to choline (green), whose nitrogen carries a permanent +1 charge. That charge is what its receptor grips.'
        : 'In the gap between nerve and muscle, the enzyme acetylcholinesterase cuts the ester bond (water supplies the missing atoms), leaving acetate and choline. The nerve ending takes choline back to make new acetylcholine. This is what keeps each signal brief.';
    },
  };
  controls.set(0);
  return {
    root,
    fit: 'both',
    metersPerUnit: 1e-10,
    view: { target: [0, 0, 0], direction: [0.2, 0.4, 1] },
    focus: [0, 0, 0],
    controls,
    update: turn,
    dispose() {
      acetylMol.sphere.dispose();
      cholineMol.sphere.dispose();
      bondGeo.dispose();
      disposeTree(root);
      M.dispose();
    },
  };
}

/** Histamine split into its imidazole ring and its charged ethylamine arm. */
export function histamineParts() {
  const { atoms, bonds } = moleculeGraph('histamine');
  const amineN = atoms.findIndex((a) => a.el === 'N' && a.charge === 1);
  // The ring: the five heavy atoms in a cycle (two N, three C); found as the atoms
  // not on the path from the charged nitrogen to the first ring carbon.
  const arm = new Set([amineN]);
  let cur = amineN;
  for (let step = 0; step < 2; step++) {
    cur = neighbors(bonds, cur).find((k) => atoms[k].el === 'C' && !arm.has(k));
    arm.add(cur);
  }
  atoms.forEach((a, i) => {
    if (a.el === 'H' && arm.has(neighbors(bonds, i)[0])) arm.add(i);
  });
  return { atoms, bonds, amineN, arm };
}

export function buildHistamine({ reducedMotion = false } = {}) {
  const M = materialBank();
  const { root, spin, update } = spinRoot(reducedMotion);
  const { atoms, bonds, amineN, arm } = histamineParts();
  atoms.forEach((a, i) => {
    const onArm = arm.has(i);
    a.tint = onArm ? 0xf2a65a : 0x5a8deb;
    a.card = 'histamine';
    a.label = i === amineN ? 'Nitrogen (carries the +1 charge)' : onArm ? 'Ethylamine arm' : a.el === 'N' ? 'Ring nitrogen (imidazole ring)' : 'Imidazole ring';
  });
  const mol = buildMolecule(atoms, bonds, M, { defaultCard: 'histamine' });
  spin.add(mol.group);
  const controls = styleControls([mol], [
    'Ball and stick: a five-membered imidazole ring (blue) with a two-carbon arm ending in a charged amine (orange). C₅H₁₀N₃⁺ at body pH, 18 atoms.',
    'Space filling: under 1 nm long. Antihistamines work by occupying the receptors this small molecule fits.',
  ]);
  controls.set(0);
  return {
    root,
    fit: 'both',
    metersPerUnit: 1e-10,
    view: { target: [0, 0, 0], direction: [0.2, 0.45, 1] },
    focus: [0, 0, 0],
    controls,
    update,
    dispose() {
      mol.sphere.dispose();
      disposeTree(root);
      M.dispose();
    },
  };
}

/** Urea: one carbonyl carbon holding an oxygen and two NH₂ groups. */
export function ureaParts() {
  const { atoms, bonds } = moleculeGraph('urea');
  const carbon = atoms.findIndex((a) => a.el === 'C');
  const oxygen = atoms.findIndex((a) => a.el === 'O');
  const nitrogens = atoms.map((a, i) => (a.el === 'N' ? i : -1)).filter((i) => i >= 0);
  return { atoms, bonds, carbon, oxygen, nitrogens };
}

export function buildUrea({ reducedMotion = false } = {}) {
  const M = materialBank();
  const { root, spin, update } = spinRoot(reducedMotion);
  const { atoms, bonds, carbon, oxygen, nitrogens } = ureaParts();
  atoms.forEach((a, i) => {
    a.card = 'urea';
    a.label = i === carbon ? 'Carbon (joined to all three heavy atoms)' : i === oxygen ? 'Oxygen (double bond to the carbon)' : a.el === 'N' ? 'Nitrogen of an amine group (–NH₂): where the body’s spare nitrogen goes' : 'Hydrogen';
  });
  const mol = buildMolecule(atoms, bonds, M, { defaultCard: 'urea' });
  spin.add(mol.group);
  const controls = styleControls([mol], [
    'Ball and stick: one carbon (violet) double-bonded to an oxygen (red) and holding two –NH₂ groups (nitrogen blue, hydrogen white). CH₄N₂O, 8 atoms, nearly flat.',
    'Space filling: about half a nanometer across. Small and uncharged, it passes the kidney’s filter easily and dissolves in water, which makes it a safe way to carry nitrogen out of the body.',
  ]);
  controls.set(0);
  return {
    root,
    fit: 'both',
    metersPerUnit: 1e-10,
    view: { target: [0, 0, 0], direction: [0.1, 0.35, 1] },
    focus: [0, 0, 0],
    controls,
    update,
    dispose() {
      mol.sphere.dispose();
      disposeTree(root);
      M.dispose();
    },
  };
}

/**
 * A thyroid hormone (T4 or T3) split at its ether oxygen: the inner ring
 * carries the amino-acid end, the outer ring the –OH. Iodines are sorted by ring.
 */
export function thyroidHormoneParts(id = 'thyroxine') {
  const { atoms, bonds } = moleculeGraph(id);
  const etherO = atoms.findIndex((a, i) => a.el === 'O' && neighbors(bonds, i).length === 2 && neighbors(bonds, i).every((k) => atoms[k].el === 'C'));
  const nitrogen = atoms.findIndex((a) => a.el === 'N');
  const inner = new Set([nitrogen]);
  const stack = [nitrogen];
  while (stack.length) {
    for (const k of neighbors(bonds, stack.pop())) {
      if (k === etherO || inner.has(k)) continue;
      inner.add(k);
      stack.push(k);
    }
  }
  const iodines = atoms.map((a, i) => (a.el === 'I' ? i : -1)).filter((i) => i >= 0);
  // The amino-acid end: the nitrogen, the alpha carbon, the carboxylate and their hydrogens.
  const alpha = neighbors(bonds, nitrogen).find((k) => atoms[k].el === 'C');
  const carboxyl = neighbors(bonds, alpha).find((k) => atoms[k].el === 'C' && neighbors(bonds, k).filter((o) => atoms[o].el === 'O').length === 2);
  const aminoEnd = new Set([nitrogen, alpha, carboxyl, ...neighbors(bonds, carboxyl).filter((k) => atoms[k].el === 'O')]);
  atoms.forEach((a, i) => a.el === 'H' && aminoEnd.has(neighbors(bonds, i)[0]) && aminoEnd.add(i));
  return {
    atoms,
    bonds,
    etherO,
    nitrogen,
    aminoEnd,
    innerIodines: iodines.filter((i) => inner.has(i)),
    outerIodines: iodines.filter((i) => !inner.has(i)),
  };
}

export const THYROID_HORMONE_VIEWS = [
  { label: 'T4 (thyroxine)', text: 'Thyroxine (T4), C₁₅H₁₁I₄NO₄: two rings joined by an oxygen, four iodine atoms (purple), and an amino-acid end (glowing green). It is built from two tyrosines. Most of what the thyroid releases is T4.' },
  { label: 'T3', text: 'T3 (triiodothyronine): the same molecule with one iodine removed from the outer ring. Cells all over the body make it from T4, and it is the more potent of the two.' },
  { label: 'Space filling', text: 'Space filling: about 1.5 nm long. The iodines are by far its biggest atoms, which is why the body needs iodine in the diet to make it.' },
];

export function buildThyroxine({ reducedMotion = false } = {}) {
  const M = materialBank();
  const { root, spin, update } = spinRoot(reducedMotion);
  const build = (id) => {
    const parts = thyroidHormoneParts(id);
    parts.atoms.forEach((a, i) => {
      a.card = 'thyroxine';
      if (parts.aminoEnd.has(i)) a.tint = 0x7cc49a;
      a.label =
        a.el === 'I'
          ? parts.innerIodines.includes(i)
            ? 'Iodine on the inner ring'
            : 'Iodine on the outer ring (T3 has one fewer here)'
          : i === parts.etherO
            ? 'Oxygen joining the two rings'
            : parts.aminoEnd.has(i)
              ? 'Amino-acid end (from tyrosine)'
              : a.el === 'O'
                ? 'Oxygen of the –OH on the outer ring'
                : a.el === 'C'
                  ? 'Ring carbon'
                  : 'Hydrogen';
    });
    return buildMolecule(parts.atoms, parts.bonds, M, { defaultCard: 'thyroxine' });
  };
  const t4 = build('thyroxine');
  const t3 = build('t3');
  spin.add(t4.group, t3.group);
  const controls = {
    label: 'Form',
    unit: '',
    min: 0,
    max: 2,
    step: 1,
    value: 0,
    format: (v) => THYROID_HORMONE_VIEWS[Math.round(v)].label,
    presets: THYROID_HORMONE_VIEWS.map((s, i) => ({ label: s.label, value: i })),
    set(v) {
      const k = Math.max(0, Math.min(2, Math.round(v)));
      controls.value = v;
      t4.group.visible = k !== 1;
      t3.group.visible = k === 1;
      t4.setStyle(k === 2 ? 1 : 0);
      return THYROID_HORMONE_VIEWS[k].text;
    },
  };
  controls.set(0);
  return {
    root,
    fit: 'both',
    metersPerUnit: 1e-10,
    view: { target: [0, 0, 0], direction: [0.15, 0.5, 1] },
    focus: [0, 0, 0],
    controls,
    update,
    dispose() {
      t4.sphere.dispose();
      t3.sphere.dispose();
      disposeTree(root);
      M.dispose();
    },
  };
}

/** Vitamin D3: its hydroxyl oxygen and the carbons of its three double bonds. */
export function vitaminD3Parts() {
  const { atoms, bonds } = moleculeGraph('vitamin-d3');
  const hydroxylO = atoms.findIndex((a) => a.el === 'O');
  const doubleBonds = bonds.filter(([, , o]) => o === 2);
  const triene = new Set(doubleBonds.flatMap(([i, j]) => [i, j]));
  return { atoms, bonds, hydroxylO, doubleBonds, triene };
}

export function buildVitaminD3({ reducedMotion = false } = {}) {
  const M = materialBank();
  const { root, spin, update } = spinRoot(reducedMotion);
  const { atoms, bonds, hydroxylO, triene } = vitaminD3Parts();
  atoms.forEach((a, i) => {
    a.card = 'vitamin-d3';
    if (triene.has(i)) a.tint = 0xffd36a;
    a.label =
      i === hydroxylO
        ? 'Oxygen of the –OH group (the liver and kidneys add two more –OH to make calcitriol)'
        : triene.has(i)
          ? 'Carbon of the three double bonds left where UV light broke open the ring'
          : a.el === 'C'
            ? 'Carbon'
            : a.el === 'H' && neighbors(bonds, i)[0] === hydroxylO
              ? 'Hydrogen of the –OH group'
              : 'Hydrogen';
  });
  const mol = buildMolecule(atoms, bonds, M, { defaultCard: 'vitamin-d3' });
  spin.add(mol.group);
  const controls = styleControls([mol], [
    'Ball and stick: vitamin D3 (cholecalciferol), C₂₇H₄₄O, 72 atoms. Built on the cholesterol skeleton, but one ring is broken open: the carbons glowing yellow carry the three double bonds left behind.',
    'Space filling: about 2 nm long and almost all carbon and hydrogen, so it dissolves in fat rather than water and travels in the blood on a carrier protein.',
  ]);
  controls.set(0);
  return {
    root,
    fit: 'both',
    metersPerUnit: 1e-10,
    view: { target: [0, 0, 0], direction: [0.15, 0.5, 1] },
    focus: [0, 0, 0],
    controls,
    update,
    dispose() {
      mol.sphere.dispose();
      disposeTree(root);
      M.dispose();
    },
  };
}

/** Retinal: its aldehyde oxygen, the ring, and the C11=C12 bond that light flips. */
export function retinalParts(id = 'retinal-11-cis') {
  const { atoms, bonds } = moleculeGraph(id);
  const heavyN = (i) => neighbors(bonds, i).filter((k) => atoms[k].el !== 'H');
  const oxygen = atoms.findIndex((a) => a.el === 'O');
  // Walk the chain from the aldehyde: O, C15, C14, C13, C12, C11 (skip the methyl branch on C13).
  const chain = [oxygen];
  while (chain.length < 6) {
    const last = chain.at(-1);
    const next = heavyN(last).find((k) => !chain.includes(k) && atoms[k].el === 'C' && heavyN(k).length >= 2);
    chain.push(next);
  }
  const [, c15, c14, c13, c12, c11] = chain;
  // Ring atoms: carbons in a six-membered cycle (each has two ring neighbors that are also connected through four more atoms).
  const ring = new Set();
  const inCycle = (start) => {
    const stack = [[start, -1, 0]];
    while (stack.length) {
      const [at, from, depth] = stack.pop();
      for (const k of heavyN(at)) {
        if (k === from) continue;
        if (k === start && depth === 5) return true;
        if (depth < 5 && k !== start) stack.push([k, at, depth + 1]);
      }
    }
    return false;
  };
  atoms.forEach((a, i) => a.el === 'C' && inCycle(i) && ring.add(i));
  return { atoms, bonds, oxygen, c11, c12, c13, c14, c15, ring };
}

export const RETINAL_VIEWS = [
  { label: '11-cis (before light)', text: '11-cis-retinal, C₂₀H₂₈O: a ring and a chain of alternating single and double bonds, bent at carbons 11 and 12 (glowing). This is the shape that sits inside rhodopsin in the dark.' },
  { label: 'all-trans (after light)', text: 'all-trans-retinal: absorbing one photon flips the double bond between carbons 11 and 12, and the chain straightens. Rhodopsin changes shape around it and the signal begins. The cell must later return it to 11-cis.' },
  { label: 'Space filling', text: 'Space filling: about 1.5 nm long. Retinal is made from vitamin A, which is why too little vitamin A causes night blindness.' },
];

export function buildRetinal({ reducedMotion = false } = {}) {
  const M = materialBank();
  const { root, spin, update } = spinRoot(reducedMotion);
  const build = (id) => {
    const p = retinalParts(id);
    p.atoms.forEach((a, i) => {
      a.card = 'retinal';
      if (i === p.c11 || i === p.c12) a.tint = 0xffd36a;
      a.label =
        i === p.c11 || i === p.c12
          ? `Carbon ${i === p.c11 ? 11 : 12}: the double bond light flips`
          : i === p.oxygen
            ? 'Oxygen of the aldehyde end (binds to the opsin protein)'
            : p.ring.has(i)
              ? 'Ring carbon'
              : a.el === 'C'
                ? 'Chain carbon'
                : 'Hydrogen';
    });
    return buildMolecule(p.atoms, p.bonds, M, { defaultCard: 'retinal' });
  };
  const cis = build('retinal-11-cis');
  const trans = build('retinal-all-trans');
  spin.add(cis.group, trans.group);
  const controls = {
    label: 'Form',
    unit: '',
    min: 0,
    max: 2,
    step: 1,
    value: 0,
    format: (v) => RETINAL_VIEWS[Math.round(v)].label,
    presets: RETINAL_VIEWS.map((s, i) => ({ label: s.label, value: i })),
    set(v) {
      const k = Math.max(0, Math.min(2, Math.round(v)));
      controls.value = v;
      cis.group.visible = k !== 1;
      trans.group.visible = k === 1;
      cis.setStyle(k === 2 ? 1 : 0);
      return RETINAL_VIEWS[k].text;
    },
  };
  controls.set(0);
  return {
    root,
    fit: 'both',
    metersPerUnit: 1e-10,
    view: { target: [0, 0, 0], direction: [0.15, 0.5, 1] },
    focus: [0, 0, 0],
    controls,
    update,
    dispose() {
      cis.sphere.dispose();
      trans.sphere.dispose();
      disposeTree(root);
      M.dispose();
    },
  };
}

/** Bilirubin: its two acid (–COOH) groups and the internal hydrogen bonds that fold it. */
export function bilirubinParts() {
  const { atoms, bonds } = moleculeGraph('bilirubin');
  const acidC = atoms
    .map((a, i) => i)
    .filter((i) => atoms[i].el === 'C' && neighbors(bonds, i).filter((k) => atoms[k].el === 'O').length === 2 && neighbors(bonds, i).some((k) => atoms[k].el === 'O' && neighbors(bonds, k).length === 2));
  const acid = new Set(acidC.flatMap((c) => [c, ...neighbors(bonds, c).filter((k) => atoms[k].el === 'O')]));
  atoms.forEach((a, i) => a.el === 'H' && acid.has(neighbors(bonds, i)[0]) && acid.add(i));
  // Hydrogen bonds: an H on N or O within 1.6–2.3 Å of an O it is not bonded to.
  const hbonds = [];
  atoms.forEach((h, i) => {
    if (h.el !== 'H') return;
    const donor = neighbors(bonds, i)[0];
    if (!['N', 'O'].includes(atoms[donor].el)) return;
    atoms.forEach((o, j) => {
      if (o.el !== 'O' || j === donor) return;
      // Skip the oxygen next door in the same –COOH group.
      if (neighbors(bonds, j).some((k) => neighbors(bonds, donor).includes(k))) return;
      const d = h.p.distanceTo(o.p);
      if (d > 1.6 && d < 2.3) hbonds.push([i, j, d]);
    });
  });
  return { atoms, bonds, acidCarbons: acidC, acid, hbonds };
}

export function buildBilirubin({ reducedMotion = false } = {}) {
  const M = materialBank();
  const { root, spin, update } = spinRoot(reducedMotion);
  const { atoms, bonds, acid, hbonds } = bilirubinParts();
  atoms.forEach((a, i) => {
    a.card = 'bilirubin';
    if (acid.has(i)) a.tint = 0x7cc49a;
    a.label = acid.has(i) ? 'Propionic acid group (–COOH); glucuronic acid is attached here' : a.el === 'N' ? 'Nitrogen of one of the four rings' : a.el === 'O' ? 'Oxygen' : a.el === 'C' ? 'Carbon' : 'Hydrogen';
  });
  const mol = buildMolecule(atoms, bonds, M, { defaultCard: 'bilirubin' });
  spin.add(mol.group);
  // Internal hydrogen bonds, drawn as thin dashed lines.
  const hb = new THREE.Group();
  const hbMat = M(0x9fd4ff, { roughness: 0.3, emissive: 0x9fd4ff, emissiveIntensity: 0.6 });
  const dash = new THREE.CylinderGeometry(0.04, 0.04, 1, 6);
  for (const [i, j] of hbonds) {
    const a = atoms[i].p;
    const b = atoms[j].p;
    for (let k = 0; k < 4; k++) {
      const p0 = a.clone().lerp(b, k / 4 + 0.03);
      const p1 = a.clone().lerp(b, k / 4 + 0.16);
      const m = new THREE.Mesh(dash, hbMat);
      m.position.copy(p0).add(p1).multiplyScalar(0.5);
      m.scale.y = p0.distanceTo(p1);
      m.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), p1.clone().sub(p0).normalize());
      m.userData = { cardId: 'bilirubin', label: 'Internal hydrogen bond (folds the molecule and hides its acid groups)' };
      hb.add(m);
    }
  }
  spin.add(hb);
  const controls = styleControls([mol], [
    `Ball and stick: bilirubin, C₃₃H₃₆N₄O₆, 79 atoms: four rings in a chain, with two acid groups (glowing green). Its own hydrogen bonds (dashed, ${hbonds.length} here) fold it shut, which is why it barely dissolves in water until the liver attaches glucuronic acid.`,
    'Space filling: about 2 nm long. Its yellow color is what makes a bruise turn yellow as it heals, and what tints the skin in jaundice.',
  ]);
  const baseSet = controls.set;
  controls.set = (v) => {
    hb.visible = v < 0.5;
    return baseSet(v);
  };
  controls.set(0);
  return {
    root,
    fit: 'both',
    metersPerUnit: 1e-10,
    view: { target: [0, 0, 0], direction: [0.15, 0.45, 1] },
    focus: [0, 0, 0],
    controls,
    update,
    dispose() {
      mol.sphere.dispose();
      dash.dispose();
      disposeTree(root);
      M.dispose();
    },
  };
}

/** Vanillin: a benzene ring carrying an aldehyde (–CHO), a methoxy (–OCH₃) and a hydroxyl (–OH). */
export function vanillinParts() {
  const { atoms, bonds } = moleculeGraph('vanillin');
  const heavy = (i) => neighbors(bonds, i).filter((k) => atoms[k].el !== 'H');
  const aldehydeO = atoms.findIndex((a, i) => a.el === 'O' && heavy(i).length === 1 && bonds.some(([x, y, o]) => o === 2 && (x === i || y === i)));
  const methoxyO = atoms.findIndex((a, i) => a.el === 'O' && heavy(i).length === 2);
  const hydroxylO = atoms.findIndex((a, i) => a.el === 'O' && i !== aldehydeO && heavy(i).length === 1);
  const groups = { aldehyde: new Set([aldehydeO, heavy(aldehydeO)[0]]), methoxy: new Set([methoxyO]), hydroxyl: new Set([hydroxylO]) };
  groups.methoxy.add(heavy(methoxyO).find((k) => neighbors(bonds, k).filter((j) => atoms[j].el === 'H').length === 3));
  atoms.forEach((a, i) => {
    if (a.el !== 'H') return;
    const h = neighbors(bonds, i)[0];
    for (const g of Object.values(groups)) if (g.has(h)) g.add(i);
  });
  return { atoms, bonds, groups };
}

export function buildVanillin({ reducedMotion = false } = {}) {
  const M = materialBank();
  const { root, spin, update } = spinRoot(reducedMotion);
  const { atoms, bonds, groups } = vanillinParts();
  const TINT = { aldehyde: 0xf2a65a, methoxy: 0x8f7ff0, hydroxyl: 0x5a8deb };
  const LABEL = { aldehyde: 'Aldehyde group (–CHO)', methoxy: 'Methoxy group (–OCH₃)', hydroxyl: 'Hydroxyl group (–OH)' };
  atoms.forEach((a, i) => {
    a.card = 'vanillin';
    const g = Object.keys(groups).find((k) => groups[k].has(i));
    if (g) {
      a.tint = TINT[g];
      a.label = LABEL[g];
    } else a.label = a.el === 'C' ? 'Ring carbon' : 'Hydrogen';
  });
  const mol = buildMolecule(atoms, bonds, M, { defaultCard: 'vanillin' });
  spin.add(mol.group);
  const controls = styleControls([mol], [
    'Ball and stick: vanillin, C₈H₈O₃, 19 atoms. A flat six-carbon ring with three groups: an aldehyde (orange), a methoxy (violet) and a hydroxyl (blue). Change them slightly and the smell changes.',
    'Space filling: under 1 nm across, small and light enough to drift out of a vanilla pod as a vapor and reach your nose.',
  ]);
  controls.set(0);
  return {
    root,
    fit: 'both',
    metersPerUnit: 1e-10,
    view: { target: [0, 0, 0], direction: [0.1, 0.4, 1] },
    focus: [0, 0, 0],
    controls,
    update,
    dispose() {
      mol.sphere.dispose();
      disposeTree(root);
      M.dispose();
    },
  };
}
